// R1: sample customer feedback. Each item = one feedback text.
const feedbacks = [
  { id: 'fb-001', customer: 'Anna',   feedback: 'Absolutely love the new dashboard! Setup took five minutes and everything just works.' },
  { id: 'fb-002', customer: 'Boris',  feedback: 'The package arrived on time. It contains what I ordered.' },
  { id: 'fb-003', customer: 'Clara',  feedback: 'THIS IS UNACCEPTABLE. Third time my order arrives broken and nobody answers my emails. I want a full refund NOW!' },
  { id: 'fb-004', customer: 'Daniel', feedback: 'Delivery was slower than promised and the packaging was a bit damaged.' },
  { id: 'fb-005', customer: 'Elena',  feedback: 'Support was fantastic, they solved my problem in minutes. Thank you!' },
  { id: 'fb-006', customer: 'Filip',  feedback: 'I was charged twice and support keeps ignoring me. Worst experience ever, I am cancelling my subscription.' },
  { id: 'fb-007', customer: 'Gergana', feedback: 'The app works. Nothing special, nothing broken.' },
  { id: 'fb-008', customer: 'Hristo', feedback: 'Great quality for the price, will definitely order again.' },
  { id: 'fb-009', customer: 'Ivan',   feedback: '   ' }  // edge case: empty text, dropped by the guard below
];

// Guard: Sentiment Analysis fails on empty text, so drop empty feedbacks.
return feedbacks
  .filter(f => f.feedback && f.feedback.trim() !== '')
  .map(f => ({ json: f }));

// R6 + R7: build ONE email from all negative feedback items (urgent cases first).
const items = $input.all().map(i => i.json);
const esc = s => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const num = v => (Number.isFinite(Number(v)) && v !== null && v !== '') ? Number(v).toFixed(2) : 'n/a';

// Urgent first, then by strength (strongest negative sentiment on top).
items.sort((a, b) => Number(b.isUrgent) - Number(a.isUrgent) || Number(b.strength) - Number(a.strength));

const urgentCount = items.filter(i => i.isUrgent).length;

const rows = items.map(i => `
  <tr style="${i.isUrgent ? 'background:#fdecea;' : ''}">
    <td style="padding:6px;border:1px solid #ddd;">${i.isUrgent ? 'URGENT' : ''}</td>
    <td style="padding:6px;border:1px solid #ddd;">${esc(i.customer)}</td>
    <td style="padding:6px;border:1px solid #ddd;">${esc(i.feedback)}</td>
    <td style="padding:6px;border:1px solid #ddd;">${num(i.strength)}</td>
    <td style="padding:6px;border:1px solid #ddd;">${num(i.confidence)}</td>
    <td style="padding:6px;border:1px solid #ddd;">${esc(i.analyzedAt)}</td>
  </tr>`).join('');

const subject = `${urgentCount > 0 ? '[URGENT] ' : ''}${items.length} negative customer feedback(s)` +
  (urgentCount > 0 ? `, ${urgentCount} urgent` : '');

const html = `
  <p>${items.length} negative feedback(s) found, ${urgentCount} marked as urgent.</p>
  <table style="border-collapse:collapse;font-family:Arial,sans-serif;font-size:14px;">
    <tr style="background:#f2f2f2;">
      <th style="padding:6px;border:1px solid #ddd;">Priority</th>
      <th style="padding:6px;border:1px solid #ddd;">Customer</th>
      <th style="padding:6px;border:1px solid #ddd;">Feedback</th>
      <th style="padding:6px;border:1px solid #ddd;">Strength</th>
      <th style="padding:6px;border:1px solid #ddd;">Confidence</th>
      <th style="padding:6px;border:1px solid #ddd;">Analyzed at</th>
    </tr>${rows}
  </table>`;

return [{ json: { subject, html } }];
